answer_text_markdown:
There are a few approaches. The event-driven approach is using p5&#39;s [`keyPressed`](https://p5js.org/reference/#/p5/keyPressed) and [`keyReleased`](https://p5js.org/reference/#/p5/keyReleased) callbacks, pulling the key&#39;s [`code`](https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/code) string from the native `KeyboardEvent` object. Adding and removing these key codes to a `pressed` set lets you implement variants of single-trigger logic.

&lt;!-- begin snippet: js hide: false console: true babel: false --&gt;

&lt;!-- language: lang-js --&gt;

    const character = {score: 0};
    const pressed = new Set();

    function setup() {
      createCanvas(600, 600);
      textSize(20);
    }

    function draw() {
      background(220);
      text(&quot;Score: &quot; + character.score, 20, 50);
    }

    function keyPressed(evt) {
      const {code} = evt;

      if (!pressed.has(code)) {
        pressed.add(code);

        if (pressed.has(&quot;KeyA&quot;) &amp;&amp; pressed.has(&quot;KeyD&quot;)) {
          character.score++;
        }
      }
    }

    function keyReleased(evt) {
      pressed.delete(evt.code);
    }

&lt;!-- language: lang-html --&gt;

    &lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.6.0/p5.js&quot;&gt;&lt;/script&gt;

&lt;!-- end snippet --&gt;

If you want to detect and take action purely in `draw`, p5.js provides [`keyIsDown`](https://p5js.org/reference/#/p5/keyIsDown) which accepts a parameter [keycode](https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/keycode).

&lt;!-- begin snippet: js hide: true console: true babel: false --&gt;

&lt;!-- language: lang-js --&gt;

    const character = {score: 0};
    const pressed = new Set();

    function setup() {
      createCanvas(600, 600);
      textSize(20);
    }

    function draw() {
      background(220);
      text(&quot;Score: &quot; + character.score, 20, 50);
      
      if (keyIsDown(65) &amp;&amp; keyIsDown(68)) {
        if ((keyIsDown(65) &amp;&amp; !pressed.has(68)) ||
            (!pressed.has(65) &amp;&amp; keyIsDown(68))) {
          character.score++;
        }

        pressed.add(65);
        pressed.add(68);
      }

      if (!keyIsDown(65)) {
        pressed.delete(65);
      }
      if (!keyIsDown(68)) {
        pressed.delete(68);
      }
    }

&lt;!-- language: lang-html --&gt;

    &lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.6.0/p5.js&quot;&gt;&lt;/script&gt;

&lt;!-- end snippet --&gt;

As mentioned, there are multiple behavioral variants you can implement. Here&#39;s a variant that prevents retriggers with the same key:

&lt;!-- begin snippet: js hide: true console: true babel: false --&gt;

&lt;!-- language: lang-js --&gt;

    const character = {score: 0};
    const pressed = new Set();

    function setup() {
      createCanvas(600, 600);
      textSize(20);
    }

    function draw() {
      background(220);
      text(&quot;Score: &quot; + character.score, 20, 50);
      
      if (keyIsDown(65) &amp;&amp; !pressed.has(65) &amp;&amp; // &#39;a&#39; and &#39;d&#39;
          keyIsDown(68) &amp;&amp; !pressed.has(68)) {
        character.score++;
        pressed.add(65);
        pressed.add(68);
      }

      if (!keyIsDown(65)) {
        pressed.delete(65);
      }
      if (!keyIsDown(68)) {
        pressed.delete(68);
      }
    }

&lt;!-- language: lang-html --&gt;

    &lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.6.0/p5.js&quot;&gt;&lt;/script&gt;

&lt;!-- end snippet --&gt;

In all above cases, the behavior lets the user press and hold one key indefinitely, then press the other. If you want these keys to be pressed on the exact same frame, or within `n` frames, you could remove the key from the set after it&#39;s been in there for `n` frames and add it to a `requireRetrigger` set that will prevent it from firing an action until it&#39;s been released. [`keyReleased`](https://p5js.org/reference/#/p5/keyReleased) might be handy here.
